/** Entity of the "audit_entries" table. */
import { Column, Entity, JoinColumn, ManyToOne, PrimaryGeneratedColumn, type Relation } from 'typeorm'
import { Order } from './order.js'

/** A row of the "audit_entries" table. */
@Entity({ name: 'audit_entries' })
export class AuditEntry {
  @PrimaryGeneratedColumn({ name: 'entry_no', type: 'int' })
  entryNo!: number

  @Column({ type: 'bigint' })
  orderId!: number

  @Column({ type: 'varchar', length: 200 })
  message!: string

  /** The Order this row points to (orderId); loaded only when asked for */
  @ManyToOne(() => Order, { nullable: false, onDelete: 'CASCADE' })
  @JoinColumn({ name: 'orderId', referencedColumnName: 'id' })
  orderIdRef?: Relation<Order>
}

