/** Entity of the "Order" table. */
import { Check, Column, Entity, JoinColumn, ManyToOne, PrimaryGeneratedColumn, Unique, type Relation } from 'typeorm'
import { Kind } from './kind.js'
import { Thing } from './thing.js'

/** A row of the "Order" table. */
@Entity({ name: 'Order' })
@Unique(['customerName'])
@Check('`group` >= 0')
export class Order {
  @PrimaryGeneratedColumn({ name: 'Id', type: 'bigint' })
  id!: number

  @Column({ type: 'varchar', length: 40 })
  user!: string

  @Column({ type: 'int', default: 0 })
  group!: number

  @Column({ type: 'varchar', length: 60 })
  customerName!: string

  @Column({ name: 'class', type: 'text', nullable: true })
  class_!: string | null

  @Column({ type: 'text', nullable: true })
  metadata!: string | null

  @Column({ type: 'date', nullable: true })
  date!: string | null

  @Column({ type: 'time', nullable: true })
  time!: string | null

  @Column({ type: 'varchar', length: 20, nullable: true })
  text!: string | null

  @Column({ type: 'text', nullable: true })
  list!: string | null

  @Column({ type: 'varchar', length: 10, nullable: true })
  str!: string | null

  @Column({ type: 'int', nullable: true })
  int!: number | null

  @Column({ type: 'date' })
  dueDate!: string

  @Column({ type: 'time', nullable: true })
  closesAt!: string | null

  @Column({ type: 'datetime', nullable: true, default: () => 'CURRENT_TIMESTAMP' })
  createdAt!: Date | null

  @Column({ name: 'kind_code', type: 'varchar', length: 10, nullable: true })
  kindCode!: string | null

  @Column({ name: 'kind_day', type: 'date', nullable: true })
  kindDay!: string | null

  @Column({ name: 'thing_id', type: 'varbinary', length: 16, nullable: true })
  thingId!: Buffer | null

  @Column({ type: 'bigint', nullable: true })
  parentId!: number | null

  /** The Thing this row points to (thing_id); loaded only when asked for */
  @ManyToOne(() => Thing, { nullable: true, onDelete: 'SET NULL' })
  @JoinColumn({ name: 'thing_id', referencedColumnName: 'id' })
  thing?: Relation<Thing>

  /** The Order this row points to (parentId); loaded only when asked for */
  @ManyToOne(() => Order, { nullable: true })
  @JoinColumn({ name: 'parentId', referencedColumnName: 'id' })
  parentIdRef?: Relation<Order>

  /** The Kind this row points to (kind_code, kind_day); loaded only when asked for */
  @ManyToOne(() => Kind, { nullable: true })
  @JoinColumn([{ name: 'kind_code', referencedColumnName: 'code' }, { name: 'kind_day', referencedColumnName: 'day' }])
  kinds?: Relation<Kind>
}

