/** Entity of the "things" table. */
import { Column, Entity, PrimaryColumn } from 'typeorm'
import { decimalText } from '../column-types.js'

/** A row of the "things" table. */
@Entity({ name: 'things' })
export class Thing {
  @PrimaryColumn({ type: 'varbinary', length: 16 })
  id!: Buffer

  @Column({ type: 'smallint' })
  tiny!: number

  @Column({ type: 'smallint' })
  small!: number

  @Column({ type: 'int', nullable: true })
  medium!: number | null

  @Column({ type: 'int', nullable: true })
  num!: number | null

  @Column({ type: 'bigint' })
  big!: number

  @Column({ type: 'decimal', precision: 10, scale: 2, transformer: decimalText })
  price!: string

  @Column({ type: 'float' })
  r!: number

  @Column({ type: 'double', nullable: true })
  d!: number | null

  @Column({ type: 'boolean', default: true })
  flag!: boolean

  @Column({ type: 'date' })
  born!: string

  @Column({ type: 'time' })
  opens!: string

  @Column({ type: 'datetime' })
  at!: Date

  @Column({ name: 'at_ts', type: 'datetime', default: () => 'CURRENT_TIMESTAMP' })
  atTs!: Date

  @Column({ type: 'datetime', nullable: true, default: () => 'CURRENT_TIMESTAMP', onUpdate: 'CURRENT_TIMESTAMP' })
  changed!: Date | null

  @Column({ type: 'varbinary', length: 50 })
  bin!: Buffer

  @Column({ type: 'blob', nullable: true })
  blobby!: Buffer | null

  @Column({ type: 'json' })
  data!: unknown

  @Column({ type: 'enum', enum: ['sad', 'ok', 'very happy'] })
  feeling!: string

  @Column({ type: 'char', length: 5 })
  code!: string

  @Column({ type: 'text', nullable: true })
  note!: string | null

  @Column({ name: 'long_note', type: 'text', nullable: true })
  longNote!: string | null

  @Column({ type: 'decimal', precision: 12, scale: 2, transformer: decimalText, nullable: true, generatedType: 'STORED', asExpression: 'price * 2', insert: false, update: false })
  total!: string | null
}

