      const value = values.group
      if (value == null) {
        if ('group' in values && !creating) errors.push({ field: 'group', message: 'cannot be empty' })
      } else {
        if (!(Number(value) >= 0)) errors.push({ field: 'group', message: 'must be >= 0' })
      }
    }
    {
      const value = values.customerName
      if (value == null) {
        if (creating || 'customerName' in values) errors.push({ field: 'customerName', message: 'is required' })
