      }
    }
    {
      const value = values.text
      if (value != null) {
        if (typeof value === 'string' && value.length > 20) errors.push({ field: 'text', message: 'is longer than 20 characters' })
      }
    }
    {
      const value = values.str
      if (value != null) {
        if (typeof value === 'string' && value.length > 10) errors.push({ field: 'str', message: 'is longer than 10 characters' })
      }
    }
